const $=s=>root.querySelector(s),persist=()=>{try{if(localStorage.getItem(KEY)!==dbSnapshot){notify(tr('Журнал изменён в другой вкладке. Обновите страницу перед сохранением.','History changed in another tab. Reload before saving.'));return false}const next=JSON.stringify(db);localStorage.setItem(KEY,next);dbSnapshot=next;return true}catch{notify(tr('Не удалось сохранить: проверьте свободное место в браузере.','Could not save: browser storage may be full.'));return false}};
