function projectOptions(value=''){return `<option value="">${tr('Весь портфель / определить по коду','Portfolio / match by code')}</option>`+state().projects.map(p=>`<option value="${esc(p.id)}" ${p.id===value?'selected':''}>${esc(p.code)} · ${esc(p.client)}${p.archived?tr(' · архив',' · archived'):''}</option>`).join('')}
