function render(){
 $('#launch').textContent=tr('✦ Секретарь','✦ Secretary');$('#secretary-title').textContent=B()?.role==='ceo'?tr('Ваш исполнительный секретарь','Your executive secretary'):tr('Ваш проектный секретарь','Your project secretary');$('.mode').textContent=tr('Деморежим · голос, команды и расчёты по данным портфеля','Demo mode · voice, commands and live portfolio calculations');$('.tabs').innerHTML=[['chat',tr('Диалог','Chat')],['mail',tr('Письма','Email')+` · ${visibleMails().length}`],['history',tr('Журнал','History')],['settings',tr('Настройки','Settings')]].map(([k,v])=>`<button data-view="${k}" class="${k===view?'active':''}">${v}</button>`).join('');
 $('.composer').hidden=view!=='chat';const main=$('main');
 if(view==='chat'){
 main.innerHTML=messages.length?messages.map(renderMessage).join(''):`<p class="intro">${B()?.role==='ceo'?tr('Компания — в одном разговоре.','Your company. One conversation.'):tr('Скажите, что нужно сделать.','Tell me what needs to happen.')}</p><p class="muted">${(['contracts','accountant'].includes(B()?.role)?tr('Проверю поступления и изменения, сохраню заметку по проекту. Управление проектами доступно координатору и руководителям.','Review receipts and changes, and record project notes. Project management is available to coordinators and managers.'):tr('Создам проект, оформлю обновление и подготовлю решения. Перед изменением покажу, что будет записано.','Create projects, capture updates and prepare decisions. Review every change before it is saved.'))}</p><div class="starters">${starters().map(([q,title,sub])=>`<button class="starter" data-query="${esc(q)}">${esc(title)}<small>${esc(sub)}</small></button>`).join('')}</div><details><summary>${tr('Как работает демонстрация','How this demonstration works')}</summary><p class="sub">${tr('Разбор типовых команд выполняется локально. OpenAI и почтовый ящик подключаются в настройках. Все цифры берутся из вашего текущего портфеля; секретарь не отправляет письма.','Common commands are processed locally. OpenAI and the mailbox can be connected in Settings. All figures come from your current portfolio; emails are not sent.')}</p></details>`;
 $('.composer').innerHTML=`<div class="context"><label for="project">${tr('Контекст','Context')}</label><select id="project">${projectOptions(selected)}</select><button id="new">${tr('Новый диалог','New chat')}</button></div><textarea id="input" aria-label="${tr('Сообщение секретарю','Message to secretary')}" placeholder="${tr('Например: Что требует моего решения сегодня?','For example: What needs my decision today?')}">${esc(input)}</textarea><div class="row"><button id="mic">${tr('◉ Говорить','◉ Speak')}</button><small id="voice-status" class="muted" role="status"></small><button id="send" class="primary">${tr('Разобрать →','Review →')}</button></div>`;
 $('#input').oninput=e=>input=e.target.value;$('#input').onkeydown=e=>{if(e.key==='Enter'&&(e.metaKey||e.ctrlKey))send()};$('#project').onchange=e=>{input=$('#input').value;selected=e.target.value;if(pending?.question&&pending.kind!=='create'){const q=pending.text;pending=null;receive(q,false,selected)}else render()};$('#send').onclick=send;$('#mic').onclick=startVoice;$('#new').onclick=()=>{stopVoice();messages=[];pending=null;source=null;voice=false;input='';render()};
 }else if(view==='mail')renderMail(main);else if(view==='settings')renderSettings(main);else renderHistory(main);
 root.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{stopVoice();cancelAI();view=b.dataset.view;render()});root.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>receive(b.dataset.query));root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{B().open(b.dataset.open);close()});root.querySelectorAll('[data-context]').forEach(b=>b.onclick=()=>{selected=b.dataset.context;input='';view='chat';textMessage(tr('Проект выбран. Что нужно изменить?','Project selected. What would you like to change?'));render()});root.querySelectorAll('[data-apply]').forEach(b=>b.onclick=()=>apply(messages[+b.dataset.apply]));root.querySelectorAll('[data-undo]').forEach(b=>b.onclick=()=>undo(b.dataset.undo));root.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(messages[+b.dataset.copy].copy);notify(tr('Текст скопирован.','Text copied.'))}catch{notify(tr('Выделите текст письма и скопируйте.','Select the email text to copy it.'))}});
}
